@media (forced-colors:active){button,[role=button],input,select{border:1px solid ButtonText!important}:focus-visible{outline:2px solid Highlight!important;box-shadow:none!important}canvas{forced-color-adjust:none}}
/* ===== POLISH layout contract (tools/t0/patches-next/POLISH.json, POLISH-README.md) =====
   One place for every floating piece of the interface, so that nothing lands on anything else at any viewport:
   LEFT RAIL (desktop, x 14..296): day badge (56..99), the Extra-menu dock (108, one row, or two rows under 1100 px), then the unit card and the Filters panel from --gt-rail-top down,
   the legend at the bottom (above the Mapbox logo).  When the unit card and the legend are both open they share the rail 62 / 38.
   RIGHT: zoom + Trails (top), the toast stack below them (180 px wide: it never reaches the story card), the story card left of the toasts, the overview at the bottom.
   CENTRE-BOTTOM: the event card (left-anchored from 312 px under 1180 px so that it clears the rail). */
:root{--gt-dock-h:148px}
@media (pointer:coarse){:root{--gt-dock-h:184px}}
:root{--gt-rail-top:160px;--gt-rail-bot:33px;--gt-rail-avail:calc(100dvh - var(--gt-rail-top) - var(--gt-dock-h,127px) - var(--gt-rail-bot))}
@media (pointer:coarse){:root{--gt-rail-bot:60px}}
@media (max-width:1099px){:root{--gt-rail-top:212px}}
html[data-layout="desktop"] #extra-features{top:108px!important;left:14px!important;right:auto!important;bottom:auto!important;transform:none!important;justify-content:flex-start;max-width:min(440px,calc(100vw - 28px))}
@media (max-width:1099px){html[data-layout="desktop"] #extra-features{max-width:270px}html[data-layout="desktop"] #ef-controls{flex-wrap:wrap;max-width:calc(100% - 52px)}}
html[data-layout="desktop"] #gt-unit-panel{top:var(--gt-rail-top)!important;max-height:calc(100dvh - var(--gt-rail-top) - var(--gt-dock-h,127px) - 12px)!important}
html[data-layout="desktop"]:has([role="group"][aria-label="Legend"]) #gt-unit-panel{max-height:calc(var(--gt-rail-avail) * .62 - 8px)!important}
html[data-layout="desktop"] [role="group"][aria-label="Filters"]{top:var(--gt-rail-top)!important;left:16px!important;border-radius:8px!important;max-height:calc(100dvh - var(--gt-rail-top) - var(--gt-dock-h,127px) - 12px)!important}
html[data-layout="desktop"] [role="group"][aria-label="Legend"],html[data-layout="desktop"] button[title="Show legend"]{bottom:calc(var(--gt-dock-h,127px) + var(--gt-rail-bot))!important}
html[data-layout="desktop"] [role="group"][aria-label="Legend"]>div:last-child{max-height:max(48px,min(320px,calc(var(--gt-rail-avail) - 64px)))!important}
html[data-layout="desktop"]:has(#gt-unit-panel) [role="group"][aria-label="Legend"]>div:last-child{max-height:max(48px,min(320px,calc(var(--gt-rail-avail) * .38 - 64px)))!important}
html[data-layout="desktop"] [data-gtbg-card="2"]{right:216px!important;max-width:min(340px,calc(100vw - 232px))!important}
html[data-layout="desktop"] [role="log"][aria-label="Battle events"]{top:164px!important;right:16px!important;max-width:180px!important;max-height:calc(100dvh - 500px);overflow:hidden;justify-content:flex-end}
html[data-layout="desktop"] [data-gtbg-card="1"]{bottom:calc(var(--gt-dock-h,127px) + 30px)!important}
@media (max-width:1179px){html[data-layout="desktop"] [data-gtbg-card="1"]{left:312px!important;bottom:calc(var(--gt-dock-h,127px) + 30px)!important;transform:none!important;width:min(460px,calc(100vw - 533px))!important}}
html[data-layout="desktop"]:has([data-gtbg-card="1"]) [data-gtbg-card="2"]{max-height:max(120px,min(calc(100dvh - 400px),calc(100dvh - var(--gt-dock-h,127px) - 102px - var(--gt-evt-h,300px))))!important}
html[data-layout="desktop"] .gtbg-tour-btn{bottom:calc(var(--gt-dock-h,127px) - 45px)!important}
/* ---- phone shell (data-layout="mobile"): the legend and the overview clear the Mapbox logo (88 x 44 at the bottom-left of the map); the cards stand above the logo too; a card hides the two small panels it would cover ---- */
html[data-layout="mobile"] .gtbg-m-legend,html[data-layout="mobile"] .gtbg-m-mini{bottom:calc(var(--gt-dock) + var(--gt-sab) + 60px)!important}
@media (orientation:portrait){
html[data-layout="mobile"] .gtbg-mp-story{bottom:calc(var(--gt-dock) + var(--gt-sab) + 52px)}
html[data-layout="mobile"] .gtbg-m-popup{bottom:calc(var(--gt-dock) + var(--gt-sab) + 52px)!important}
html[data-layout="mobile"] .gtbg-m-root:has(.gtbg-mp-story>*) :is(.gtbg-m-legend,.gtbg-m-mini),html[data-layout="mobile"] .gtbg-m-root:has(>.gtbg-m-popup) :is(.gtbg-m-legend,.gtbg-m-mini){visibility:hidden}
}
@media (orientation:landscape) and (max-height:480px){html[data-layout="mobile"] .gtbg-m-popup{left:auto!important;width:min(420px,52vw)!important;box-sizing:border-box}}
html[data-layout="mobile"] .gtbg-mp-toast{right:calc(max(8px,var(--gt-sar)) + 36px)}
@media (orientation:landscape) and (max-height:480px){html[data-layout="mobile"] .gtbg-mp-story{right:calc(max(8px,var(--gt-sar)) + 40px)}}
@media (orientation:portrait){
html[data-layout="mobile"] .gtmon-sheet:not(.gtmon-side){bottom:calc(var(--gt-dock,0px) + var(--gt-sab,0px) + 52px)!important}
}
html[data-layout="mobile"]:has(.gtmon-sheet) :is(.gtbg-m-legend,.gtbg-m-mini){visibility:hidden}
@media (orientation:landscape) and (max-height:480px){html[data-layout="mobile"] .gtmon-sheet.gtmon-side{max-height:max(120px,calc(var(--gt-maph) - 62px))!important}}
html[data-layout="mobile"]:has(.gtmon-sheet) .gtbg-mp-story{visibility:hidden;pointer-events:none}
/* ---- targets: 32 px minimum for every control of the map on a fine pointer; on touch the shipped rule above already gives 44 px, and the toolbar's icon buttons get as much width as the bar has ---- */
@media (pointer:fine){
#root button,#extra-features button,#extra-features a{min-height:32px}
#root a[href]:not(.mapboxgl-ctrl a){min-height:32px;box-sizing:border-box}
html #ef-toggle{width:32px;height:32px}
.mapboxgl-ctrl-group button{min-width:32px;min-height:32px}
#gt-timeline div:has(>input[aria-label="Battle time"]){height:32px!important}
#gt-timeline input[aria-label="Battle time"]{height:32px!important}
}
@media (pointer:fine) and (min-width:1100px){#root button:not(.mapboxgl-ctrl button):not([aria-hidden="true"]){min-width:32px}}
@media (pointer:coarse){#gt-timeline div:has(>input[aria-label="Battle time"]){height:44px!important}#gt-timeline input[aria-label="Battle time"]{height:44px!important}}
@media (pointer:coarse) and (min-width:1000px){#root .gtbg-tb-right button{min-width:44px}}
@media (pointer:coarse) and (min-width:835px) and (max-width:1319px){html[data-layout="desktop"] .gtbg-tb-center a[download]{display:none!important}}
@media (pointer:coarse) and (min-width:835px) and (max-width:1099px){html[data-layout="desktop"] .gtbg-tb-center>div>button:first-child{display:none!important}}
#root a[href^="mailto:"]{display:inline-flex;align-items:center;min-height:32px}
@media (pointer:coarse){#root a[href^="mailto:"]{min-height:44px}}
/* ---- User Guide and Toggle Units keep a home at every width: the toolbar drops them when it has no room (the shipped rules hide the guide link under 990 px and Toggle Units under 850 px; on touch the rules above hide them under 1320 and 1100 px), so the More to Explore menu carries them exactly then (see PG-polish POL-U10) ---- */
#ef-menu .gtbg-group-tools .gtbg-item{width:100%;box-sizing:border-box;margin:0;background:none;border:0;font:inherit;color:inherit;text-align:left;cursor:pointer;min-height:44px}
#ef-menu .gtbg-group-tools .gtbg-item[aria-pressed="false"] .gtbg-item-icon{opacity:.55}
@media (pointer:fine) and (min-width:850px){#ef-menu .gtbg-tool-units{display:none}}
@media (pointer:coarse) and (min-width:1100px){#ef-menu .gtbg-tool-units{display:none}}
@media (pointer:fine) and (min-width:990px){#ef-menu .gtbg-tool-guide{display:none}}
@media (pointer:coarse) and (min-width:1320px){#ef-menu .gtbg-tool-guide{display:none}}
@media (pointer:fine) and (min-width:990px){#ef-menu .gtbg-group-tools{display:none}}
@media (pointer:coarse) and (min-width:1320px){#ef-menu .gtbg-group-tools{display:none}}
